int ds10_tables_builtin(ds10_table_set *s)
{
    memset(s, 0, sizeof *s);
    s->t.env_rate = env_rate;
    s->t.lfo_bpm = lfo_bpm;
    s->t.lfo_free = lfo_free;
    s->t.porta = porta;
    s->t.peak = peak;
    s->t.pitch = pitch;
    s->t.depth = depth;
    s->t.mod_a = mod_a;
    s->t.mod_b = mod_b;
    s->t.coef = coef;
    s->fx.lfo_phase_off = fx_lfo_phase;
    s->fx.flanger_fb = fx_flanger_fb;
    s->fx.depth = fx_depth;
    s->fx.delay_div = fx_delay_div;
    s->fx.lfo_rate = fx_lfo_rate;
    s->drum_pitch = drum_pitch;
    s->voice_init = voice_init;
    s->mixer_init = mixer_init;
    s->fx_init = fx_init;
    s->knob_min = knob_min;
    s->knob_range = knob_range;
    return 0;
}
